import {initVoiceDemo} from './voice.js';
import {EXAMPLES,todayISO,greeting,replyFor,validateRequest,csvFor} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='amjads-demo-agent-v1';
let data;try{data=JSON.parse(localStorage.getItem(KEY)||'null')}catch{};
if(!data||!Array.isArray(data.profiles)||!Array.isArray(data.requests)||!data.chats||!EXAMPLES.every(p=>data.profiles.some(q=>q.id===p.id)))data={profiles:structuredClone(EXAMPLES),requests:[],chats:{}};
let current='hotel',channel='website',page='voice',mode='booking',lastReply='',toastTimer;
let voiceDemo=null;
const makeId=()=>globalThis.crypto?.randomUUID?.() || 'demo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
const profile=()=>data.profiles.find(p=>p.id===current),rows=()=>data.requests.filter(r=>r.business===current),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{toast('Browser storage is unavailable or full. Your changes will last only while this page stays open.')}}
function chat(){const k=current+':'+channel;if(!data.chats[k])data.chats[k]=[{role:'assistant',text:greeting(profile())}];return data.chats[k]}
function stats(){const counts=Object.entries(data.chats).filter(([k,v])=>k.startsWith(current+':')&&v.some(m=>m.role==='user')).length;$('#statChats').textContent=counts;$('#statBookings').textContent=rows().filter(r=>r.type==='Booking').length;$('#statPending').textContent=rows().filter(r=>r.status==='Pending').length;$('#navCount').textContent=rows().filter(r=>r.status==='Pending').length}
function renderChat(){const messages=chat();$('#chatMessages').innerHTML=messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><span class="message-label">${m.role==='user'?'YOU':escape(profile().agent).toUpperCase()}</span><div class="bubble">${escape(m.text)}${m.action?`<button class="button small" data-action="${m.action}">${m.action==='booking'?'Create a booking request':'Leave a message for staff'} ↗</button>`:''}</div></div>`).join('');lastReply=[...messages].reverse().find(m=>m.role==='assistant')?.text||'';$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;stats()}
function renderProfile(){const p=profile();$('#businessSelect').innerHTML=data.profiles.map(p=>`<option value="${p.id}">${escape(p.name)} · ${p.kind==='hotel'?'Hotel':p.kind==='salon'?'Salon':'Services'}</option>`).join('');$('#businessSelect').value=current;$('#businessName').textContent=p.name;$('#agentName').textContent=p.agent;$('#profileCategory').textContent=p.category;$('#businessDescription').textContent=p.description;$('#businessLocation').textContent=p.location;$('#businessHours').textContent=p.hours;$('.cover-number').textContent=String(EXAMPLES.findIndex(x=>x.id===p.id)+1).padStart(2,'0');
 const captions={website:'Website chat · local demo',whatsapp:'WhatsApp conversation simulation',phone:'Phone conversation simulation'};$('#channelCaption').textContent=captions[channel];$('#channelFoot').textContent=channel==='website'?'Local website chat':channel==='whatsapp'?'No WhatsApp messages sent':'No phone calls placed';$('#phoneControls').hidden=channel!=='phone';$$('[data-channel]').forEach(b=>{b.classList.toggle('selected',b.dataset.channel===channel);b.setAttribute('aria-pressed',String(b.dataset.channel===channel))});
 $('#suggestions').innerHTML=(p.kind==='hotel'?['What are your room prices?','Check-in time?','Request a stay','Speak to staff']:['What services do you offer?','Opening hours?','Book an appointment','Speak to staff']).map(s=>`<button data-prompt="${escape(s)}">${escape(s)}</button>`).join('');
 for(const key of ['name','agent','description','location','hours','policy','extra'])$('#knowledgeForm').elements[key].value=p[key]||'';
 renderChat();renderRequests();voiceDemo?.refresh();}
function navigate(next){if(page==='voice'&&next!=='voice')voiceDemo?.stop();page=next;$$('.page').forEach(el=>el.hidden=el.id!==next+'Page');$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===next));$('#pageTitle').textContent={voice:'Voice receptionist',reception:'Chat receptionist',inbox:'Requests',knowledge:'Business knowledge',guide:'Demo guide'}[next];if(next==='inbox')renderRequests();window.scrollTo({top:0,behavior:'smooth'})}
function send(text){if(!text.trim())return;const r=replyFor(text.trim(),profile());chat().push({role:'user',text:text.trim()},{role:'assistant',...r});persist();renderChat();$('#messageInput').value=''}
function openRequest(type='booking'){
 mode=type;const p=profile(),form=$('#bookingForm');form.reset();$('#formError').textContent='';$('#dialogKicker').textContent=type==='booking'?'CAPTURE A BOOKING REQUEST':'A HUMAN TOUCH';$('#dialogTitle').textContent=type==='booking'?'Let’s get the details.':'Leave a message for the team.';
 for(const id of ['serviceLabel','dateLabel','endLabel','timeLabel','partyLabel'])$('#'+id).hidden=type==='handoff'||(id==='timeLabel'?p.kind==='hotel':(id==='endLabel'||id==='partyLabel')?p.kind!=='hotel':false);
 form.elements.service.innerHTML=p.services.map(s=>`<option>${escape(s.name)}</option>`).join('');form.elements.date.min=todayISO();form.elements.end.min=todayISO();form.elements.date.required=type==='booking';form.elements.service.required=type==='booking';form.elements.end.required=type==='booking'&&p.kind==='hotel';form.elements.time.required=type==='booking'&&p.kind!=='hotel';form.elements.notes.required=type==='handoff';
 if(p.kind!=='hotel'){form.elements.time.min=p.kind==='salon'?'09:00':'08:00';form.elements.time.max='17:59'}$('#bookingDialog').showModal();
}
function statusActions(r){if(r.status!=='Pending')return '';return `<button class="button small" data-id="${r.id}" data-status="${r.type==='Booking'?'Confirmed':'Resolved'}">${r.type==='Booking'?'Confirm in demo':'Mark resolved'}</button><button class="button secondary small" data-id="${r.id}" data-status="Cancelled">Cancel request</button>`}
function renderRequests(){let requests=rows();const filter=$('#statusFilter').value,search=$('#requestSearch').value.toLowerCase();requests=requests.filter(r=>(filter==='all'||r.status===filter)&&[r.customer,r.contact].some(s=>s.toLowerCase().includes(search)));$('#requestList').innerHTML=requests.length?requests.toReversed().map(r=>`<article class="request-card"><div class="request-top"><div><h3>${escape(r.customer)}</h3><small>${escape(r.type)} · ${escape(r.channel)} simulation · ${r.id.slice(0,8)}</small></div><span class="pill ${r.status.toLowerCase()}">${r.status}</span></div><div class="request-body"><p><span>CONTACT</span>${escape(r.contact)}</p><p><span>REQUEST</span>${escape(r.service||'Staff follow-up')}</p>${r.date?`<p><span>${profile().kind==='hotel'?'STAY DATES':'PREFERRED VISIT'}</span>${escape(r.date)}${r.end?' → '+escape(r.end):' at '+escape(r.time)}</p>`:''}${r.party?`<p><span>GUESTS</span>${escape(r.party)}</p>`:''}${r.notes?`<p class="request-note"><span>MESSAGE</span>${escape(r.notes)}</p>`:''}</div><div class="request-bottom">${statusActions(r)}<small>Local demo record · no external notifications</small></div></article>`).join(''):`<div class="empty-state"><span class="symbol">▤</span><h3>${rows().length?'No matching requests.':'A clear desk. A fresh start.'}</h3><p>${rows().length?'Try another filter or search.':'Create a booking request in the demo to see the staff workflow here.'}</p><button class="button secondary" id="inboxCreate">Try a booking request ↗</button></div>`;stats()}
$('#chatForm').addEventListener('submit',e=>{e.preventDefault();send($('#messageInput').value)});
$('#chatMessages').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)openRequest(b.dataset.action)});
$('#suggestions').addEventListener('click',e=>{const b=e.target.closest('[data-prompt]');if(b)send(b.dataset.prompt)});
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
$$('[data-channel]').forEach(b=>b.addEventListener('click',()=>{if('speechSynthesis'in window)window.speechSynthesis.cancel();channel=b.dataset.channel;renderProfile()}));
$('#businessSelect').addEventListener('change',e=>{voiceDemo?.stop();if('speechSynthesis'in window)window.speechSynthesis.cancel();current=e.target.value;$('#statusFilter').value='all';$('#requestSearch').value='';renderProfile()});
$('#restartChat').addEventListener('click',()=>{data.chats[current+':'+channel]=[{role:'assistant',text:greeting(profile())}];persist();renderChat();toast('This channel’s conversation has been restarted.')});
$('#openBooking').addEventListener('click',()=>openRequest());$('#editBusiness').addEventListener('click',()=>navigate('knowledge'));$('#helpButton').addEventListener('click',()=>navigate('guide'));$('.brand').addEventListener('click',e=>{e.preventDefault();navigate('voice')});$('#closeDialog').addEventListener('click',()=>$('#bookingDialog').close());
$('#bookingForm').addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),p=profile(),error=validateRequest(d,p,mode);if(error){$('#formError').textContent=error;return}const row={id:makeId(),business:current,businessName:p.name,type:mode==='booking'?'Booking':'Handoff',customer:d.customer.trim(),contact:d.contact.trim(),service:mode==='booking'?d.service:'',date:mode==='booking'?d.date:'',end:mode==='booking'&&p.kind==='hotel'?d.end:'',time:mode==='booking'&&p.kind!=='hotel'?d.time:'',party:mode==='booking'&&p.kind==='hotel'?d.party:'',notes:d.notes.trim(),channel,status:'Pending',created:new Date().toISOString()};data.requests.push(row);chat().push({role:'assistant',text:`Thanks, ${row.customer}. Your ${mode==='booking'?'booking request':'message'} is saved in the local demo inbox (${row.id.slice(0,8)}). Staff review is needed. No real booking or notification has been made.`});persist();$('#bookingDialog').close();renderChat();renderRequests();toast('Request saved. Open Requests to review it.');});
$('#bookingForm').elements.date.addEventListener('change',e=>{const next=new Date(e.target.value+'T12:00:00');if(!Number.isNaN(next.getTime())){next.setDate(next.getDate()+1);$('#bookingForm').elements.end.min=todayISO(next)}});
$('#requestList').addEventListener('click',e=>{const b=e.target.closest('[data-status]');if(b){const r=rows().find(x=>x.id===b.dataset.id);if(r&&r.status==='Pending'){r.status=b.dataset.status;persist();renderRequests();toast(`Demo request ${r.status.toLowerCase()}. No notification sent.`)}}if(e.target.closest('#inboxCreate'))openRequest()});
$('#statusFilter').addEventListener('change',renderRequests);$('#requestSearch').addEventListener('input',renderRequests);
$('#knowledgeForm').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(Object.entries(values).some(([k,v])=>k!=='extra'&&!v.trim())){toast('Please fill in all required profile details.');return}Object.assign(profile(),Object.fromEntries(Object.entries(values).map(([k,v])=>[k,v.trim()])));persist();renderProfile();toast('Profile saved. New replies use your updated knowledge.')});
$('#restoreProfile').addEventListener('click',()=>{const i=data.profiles.findIndex(p=>p.id===current);data.profiles[i]=structuredClone(EXAMPLES.find(p=>p.id===current));persist();renderProfile();toast('Example profile restored.')});
$('#clearData').addEventListener('click',()=>{voiceDemo?.stop();if(!window.confirm('Clear all local demo requests, conversations, and profile changes?'))return;data={profiles:structuredClone(EXAMPLES),requests:[],chats:{}};current='hotel';channel='website';persist();renderProfile();navigate('voice');toast('All demo data cleared.')});
$('#exportRequests').addEventListener('click',()=>{if(!rows().length){toast('Create a request before exporting.');return}const blob=new Blob(['\uFEFF'+csvFor(rows())],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`amjad-${current}-requests.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Demo requests exported.')});
$('#listen').addEventListener('click',()=>{voiceDemo?.stop();if(!('speechSynthesis'in window)){toast('Voice playback is unavailable in this browser. The transcript still works.');return}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(lastReply);utterance.lang='en-US';utterance.rate=.95;utterance.onerror=()=>toast('Voice playback could not start. You can use the transcript.');window.speechSynthesis.speak(utterance)});
renderProfile();
voiceDemo=initVoiceDemo({getProfile:profile,onTranscript:messages=>{data.chats[current+':voice']=messages;persist();stats()},saveRequest:(draft,transcript)=>{const row={...draft,id:makeId(),business:current,businessName:profile().name,channel:'voice',status:'Pending',created:new Date().toISOString(),notes:[draft.notes||'', 'Captured in a browser voice demonstration.'].filter(Boolean).join(' ')};data.requests.push(row);persist();renderRequests();toast('Voice request saved in the demo inbox.');return row},openInbox:()=>navigate('inbox')});
navigate('voice');
